<?php require_once 'config.php';$cat=(int)($_GET['category']??0);$q=trim($_GET['q']??'');$sql="SELECT * FROM products WHERE 1";$args=[];if($cat){$sql.=" AND category_id=?";$args[]=$cat;}if($q){$sql.=" AND name LIKE ?";$args[]="%$q%";}$st=$pdo->prepare($sql);$st->execute($args);$items=$st->fetchAll();$title='Shop';include 'header.php';?><div class="banner"><h1>Shop all things lovely</h1><p class="muted">Find your next everyday favourite.</p></div><form class="d-flex mb-4" method="get"><input class="form-control" name="q" placeholder="Search products" value="<?= h($q) ?>"><button class="btn btn-rose ms-2">Search</button></form><div class="row g-4"><?php foreach($items as $p): ?><div class="col-6 col-md-3"><div class="card"><a href="product.php?id=<?= $p['id'] ?>"><img class="card-img-top" src="<?= h($p['image_url']) ?>"></a><div class="card-body"><h5><?= h($p['name']) ?></h5><p class="price"><?= money($p['price']) ?></p><a class="btn btn-rose" href="product.php?id=<?= $p['id'] ?>">View</a></div></div></div><?php endforeach; ?><?php if(!$items): ?><p>No products found.</p><?php endif; ?></div><?php include 'footer.php'; ?>
